// Package enc is Google's libwebp encoder (third_party/libwebp) plus ../csrc/enc.c, compiled
// to WebAssembly with wasi-sdk and translated to Go with wasm2go. libwebp.go is generated by
// `make generate` from the pinned inputs in ../toolchain.env and ../flags.env; do not edit it.
package enc

// Mem returns the module's linear memory. The slice is replaced when the memory grows (any call
// into the module may grow it), so callers must fetch it again after every call.
func (m *Module) Mem() []byte { return m.memory }
